    top_module dut (
        .CHANNEL(CHANNEL),
        .CLK(CLK),
        .REQUEST(REQUEST),
        .SDI(SDI),
        .BUSY(BUSY),
        .CONV_RESULT(CONV_RESULT),
        .CS(CS),
        .SCLK(SCLK),
        .SDO(SDO)
    );

    // Clock generation (10ns period)
    initial begin
        CLK = 0;
        forever #5 CLK = ~CLK;
