            SDI = 0;

            repeat(5) @(posedge CLK);
        end
        endtask
    task simulate_sdi_stream;

        input [11:0] data_to_receive;
        integer i;
        begin

            wait(CS == 0);



            for (i = 11; i >= 0; i = i - 1) begin
                @(negedge SCLK);
