            @(posedge CLK);
            REQUEST = 0;

            fork
                simulate_sdi_stream(12'h555);
            join_none

            wait(BUSY == 1);
            wait(BUSY == 0);
            repeat(5) @(posedge CLK);

            #1;


            check_outputs(0, 12'h555, 1, 0, SDO);
        end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
