                $display("  Got:      BUSY=%b, CONV_RESULT=%h, CS=%b, SCLK=%b, SDO=%b",
                         BUSY, CONV_RESULT, CS, SCLK, SDO);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
