module bcd_counter(
  input clk,
  input rst_n,
  output reg [3:0] bcd
);

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      bcd <= 4'b0000;
    end
    else begin
      if (bcd == 4'b1001)
        bcd <= 4'b0000;
      else
        bcd <= bcd + 1;
    end
  end

endmodule

