description:
Design a 32-frequency clock divider that generates a secondary clock signal (s_clk) from an input clock (clk). The module counts clock cycles up to 35, and upon reaching this count, it toggles the s_clk output and resets the count back to zero. The operation can be reset asynchronously using the reset signal, which sets both s_clk and the count to zero.
module top_module(
	input wire clk,       
	input wire reset,     
	output reg s_clk      
    );

code:
module top_module(
	input wire clk,       
	input wire reset,     
	output reg s_clk      
    );reg [5:0] cuenta; 


always @(posedge clk,posedge reset) 
	begin
		if (reset) 
			begin
				s_clk <= 0;
				cuenta <= 0;
			end 
		else 
			begin		
				if (cuenta == 6'd35)

					begin                    
						cuenta <= 6'h0;  
						s_clk <= ~s_clk;  
					end 
				else 
					cuenta <= cuenta + 1'b1; 
			end
	end

endmodule

