module top_module(
    input clk,
    input d,
    input areset,    // Asynchronous active-high reset to zero
    input load,
    input ena,
    input [3:0] data,
    output reg [3:0] q,
    output final_out
);// Dual-edge triggered flip-flop
    reg [1:0] dff_out;
    always @(posedge clk, negedge clk) begin
        dff_out <= {dff_out[0], d};
    end

    // 4-bit shift register
    reg [3:0] shift_reg;
    always @(posedge clk) begin
        if (areset) begin
            shift_reg <= 4'b0;
        end else if (load) begin
            shift_reg <= data;
        end else if (ena) begin
            shift_reg <= {shift_reg[2:0], 1'b0};
        end
    end

    // Functional module
    assign final_out = dff_out[0] | shift_reg[0];
    assign q = shift_reg;

endmodule

