    assign y[5] = x[0]&(~x[1])&x[2];
    assign y[4] = x[0]&(~x[1])&(~x[2]);
    assign  y[3] = x[1]&x[2];
    assign y[2] = (~x[0])&x[1]&(~x[2]);
