module up_down_counter_4bit(CLK, RESET, UP_DOWN, COUNT);
input CLK, RESET, UP_DOWN;
output reg [3:0] COUNT;

always @(posedge CLK or posedge RESET) begin
    if (RESET)
        COUNT <= 4'b0000;
    else if (UP_DOWN)
        COUNT <= COUNT + 1;
    else
        COUNT <= COUNT - 1;
end

endmodule

