module top_module (
        input clk,
        input areset,
        input go_up,
        input go_down,
        output reg at_ground,
        output reg at_first,
        output reg at_second);parameter Ground=2'b00, First=2'b01, Second=2'b10;
	reg [1:0] state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Ground;
		else begin
			case (state)
				Ground: state <= go_up ? First : Ground;
				First: state <= go_up ? Second : (go_down ? Ground : First);
				Second: state <= go_down ? First : Second;
			endcase
		end
	end

	assign {at_ground, at_first, at_second} = (state == Ground) ? 3'b100 :
	                                          (state == First) ? 3'b010 : 3'b001;

endmodule

