module fsm (
        input clk,
        input reset,
        input z,
        output reg y);parameter M0=0, M1=1, M2=2, M3=3;
	reg [1:0] state, next;

	always @(posedge clk)
		if (reset)
			state <= M0;
		else 
			state <= next;


	always_comb begin
		case(state)
			M0: next = z ? M2 : M1;
			M1: next = z ? M0 : M3;
			M2: next = z ? M1 : M3;
			M3: next = z ? M2 : M1;
			default: next = 'x;
		endcase
	end

	assign y = (state == M0 || state == M2);

endmodule

