description:
Design a 32-bit arithmetic unit that performs addition or subtraction based on the control signals. The module takes two 32-bit inputs, `data_a` and `data_b`, along with a `sign` indicator and an `addsub` control signal to determine the operation. When `addsub` is high, the unit performs subtraction, differentiating between signed and unsigned arithmetic based on the `sign` input, producing an overflow flag if needed. If `addsub` is low, the unit performs addition in a similar manner, also accounting for signed or unsigned behavior and outputting an overflow flag. The result of the operation is provided on the `data_c` output.
module top_module(/*AUTOARG*/
	// Outputs
	data_c, overflow,
	// Inputs
	data_a, data_b, sign, addsub
	);

code:
module top_module(/*AUTOARG*/
	// Outputs
	data_c, overflow,
	// Inputs
	data_a, data_b, sign, addsub
	);input  [31:0]    data_a;
	input  [31:0]    data_b;
	input             sign;
	input             addsub;

	output reg        overflow; // changed to reg
	output reg [31:0] data_c;

	reg [32:0] temp;

	always @(*) begin
		overflow = 0; // Initialize overflow
		if (addsub == 1) begin // subtraction
			if (sign == 1) begin // signed subtraction
				if (data_a < data_b) begin
					temp = {32'h0, data_b} - {32'h0, data_a};
					data_c = -temp[31:0];
					overflow = 1;
				end else begin
					temp = {32'h0, data_a} - {32'h0, data_b};
					data_c = temp[31:0];
					overflow = 0;
				end
			end else begin // unsigned subtraction
				if (data_a < data_b) begin
					temp = {32'h0, data_b} - {32'h0, data_a};
					data_c = temp[31:0];
					overflow = 1;
				end else begin
					temp = {32'h0, data_a} - {32'h0, data_b};
					data_c = temp[31:0];
					overflow = 0;
				end
			end
		end else begin // addition
			if (sign == 1) begin // signed addition
				temp = {32'h0, data_a[31] ^ sign, data_a[30:0]} + {32'h0, data_b[31] ^ sign, data_b[30:0]};
				if (temp[32] != temp[31]) begin
					overflow = 1;
				end
				data_c = temp[31:0];
			end else begin // unsigned addition
				temp = {32'h0, data_a} + {32'h0, data_b};
				if (temp[32] != 0) begin
					overflow = 1;
				end
				data_c = temp[31:0];
			end
		end
	end

endmodule

