module top_module (
  input in1,
  input in2,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter T=0, U=1, V=2;

    always_comb begin
        case (state)
            T: next_state = in1 ? V : U;
            U: next_state = in2 ? T : V;
            V: next_state = in2 ? U : T;
        endcase
    end

    assign out = (state == U);

endmodule

