module top_module(
    input clk,
    input rst_n,
    output reg clk_out,
    input [1:0] select
);reg [23:0] counter;
reg [23:0] divider;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        counter <= 24'd0;
        clk_out <= 1'b0;
    end
    else begin
        case (select)
            2'b00: divider <= 24'd5;
            2'b01: divider <= 24'd5999999;
            2'b10: divider <= 24'd5999;
            2'b11: divider <= 24'd5;
        endcase

        if (counter == divider) begin
            counter <= 24'd0;
            clk_out <= ~clk_out;
        end
        else begin
            counter <= counter + 1;
        end
    end
end

endmodule

