module top_module(input clk, input UART_RX, output [7:0] data, output send);parameter IDLE = 2'b00, START = 2'b01, DATA = 2'b10, STOP = 2'b11;
  reg [8:0] recvbuf;
  reg [5:0] bitcnt = 0;
  reg [1:0] state = IDLE;
  reg data_valid = 0;
  assign data = recvbuf[7:0];
  assign send = data_valid;

  always @(posedge clk) begin
    case(state)
      IDLE: begin
        if(UART_RX == 0) begin
          state <= START;
          bitcnt <= 0;
        end
      end
      START: begin
        if(bitcnt == 0) begin
          if(UART_RX == 0) begin
            bitcnt <= bitcnt + 1;
          end else begin
            state <= IDLE;
          end
        end else begin
          state <= DATA;
          bitcnt <= 0;
        end
      end
      DATA: begin
        if(bitcnt == 8) begin
          state <= STOP;
          bitcnt <= 0;
        end else begin
          recvbuf[bitcnt] <= UART_RX;
          bitcnt <= bitcnt + 1;
        end
      end
      STOP: begin
        if(bitcnt == 0) begin
          if(UART_RX == 1) begin
            state <= IDLE;
            data_valid <= 1;
          end else begin
            state <= IDLE;
          end
        end else begin
          bitcnt <= bitcnt + 1;
        end
      end
    endcase
  end
endmodule

