description:
Design a clock gating circuit that inhibits clock signals based on an enable signal (EN) and a temporary enable signal (TE). When TE is low, the first flip-flop (ff1) resets, preventing clock propagation; otherwise, it captures the state of EN. The output of ff1 is then ANDed with EN to produce a gated clock (gated_clk). This gated clock is latched by the second flip-flop (ff2) on the rising edge of the CLK, providing the final output ENCLK, which allows the clock signal to pass through only when both EN and TE conditions are met.
module top_module(
  input CLK, EN, TE,
  output ENCLK
);

code:
module top_module(
  input CLK, EN, TE,
  output ENCLK
);wire gated_clk;
  reg ff1, ff2;

  // D flip-flop with asynchronous reset
  always @(posedge CLK or negedge TE) begin
    if (~TE) begin
      ff1 <= 0;
    end else begin
      ff1 <= EN;
    end
  end

  // AND gate
  assign gated_clk = ff1 & EN;

  // D flip-flop
  always @(posedge CLK) begin
    ff2 <= gated_clk;
  end

  assign ENCLK = ff2;

endmodule

