module top_module(
    input clk,
    input reset,
    input parallel_load,
    input shift,
    input [3:0] input_data,
    output reg [2:0] output_data
);reg [7:0] shift_reg;
    reg [2:0] decoder_out;

    // Parallel load
    always @(posedge clk, negedge reset) begin
        if (!reset) begin
            shift_reg <= 8'b0;
        end else if (parallel_load) begin
            shift_reg <= input_data;
        end
    end

    // Shift left
    always @(posedge clk, negedge reset) begin
        if (!reset) begin
            shift_reg <= 8'b0;
        end else if (shift) begin
            shift_reg <= {shift_reg[6:0], 1'b0};
        end
    end

    // Decode
    always @(shift_reg) begin
        case (shift_reg[7:5])
            3'b000: decoder_out <= 3'b001;
            3'b001: decoder_out <= 3'b010;
            3'b010: decoder_out <= 3'b100;
            3'b011: decoder_out <= 3'b000;
            3'b100: decoder_out <= 3'b000;
            3'b101: decoder_out <= 3'b000;
            3'b110: decoder_out <= 3'b000;
            3'b111: decoder_out <= 3'b000;
            default: decoder_out <= 3'b000;
        endcase
    end

    // Output
    always @(decoder_out) begin
        output_data <= decoder_out;
    end

endmodule

module top_module(clk, cs, mosi, miso, sck, done, din, dout);parameter bc=8;	

	input clk;
	input cs;	
	input mosi;
	output miso;
	input sck;
	output reg done;
	input [bc-1:0] din;
	output reg [bc-1:0] dout;

	reg [bc-1:0] shift_reg;
	reg prev_cs, prev_sck;
	reg mosi_sample;
	reg [7:0] shift_count;

	assign miso = shift_reg[bc-1];

	always @(posedge clk) begin
		if (~cs) begin
			if (prev_cs) begin

				done <= 0;
				shift_reg[bc-1:0] <= 8'h23; 
				shift_count <= 0;
			end else begin
				if (~prev_sck && sck) begin

					mosi_sample <= mosi;
					if (shift_count == bc-1) begin
						dout <= {shift_reg[bc-2:0], mosi};
						done <= 1;
					end
				end 
				if (prev_sck && ~sck) begin

					shift_reg[bc-1:0] <= {shift_reg[bc-2:0], mosi_sample};
					shift_count <= shift_count + 1;
				end
			end
		end else begin
			done <= 1;
		end
		prev_cs <= cs;
		prev_sck <= sck;
	end
endmodule

