module top_module(
  input enable_charging,
  input clk_charging,
  input [7:0] voltage_charging,
  output [7:0] charge_current,

  input enable_discharging,
  input clk_discharging,
  input [7:0] voltage_discharging,
  output [7:0] discharge_current,

  input [7:0] voltage_monitoring,
  output alarm
);reg [7:0] charge_current_reg;
  reg [7:0] discharge_current_reg;
  reg alarm_reg;

  always @(posedge clk_charging) begin
    if (enable_charging) begin
      charge_current_reg <= voltage_charging;
    end else begin
      charge_current_reg <= 8'b0;
    end
  end

  always @(posedge clk_discharging) begin
    if (enable_discharging) begin
      discharge_current_reg <= voltage_discharging;
    end else begin
      discharge_current_reg <= 8'b0;
    end
  end

  always @(*) begin
    if (voltage_monitoring < 8'h20) begin
      alarm_reg = 1'b1;
    end else begin
      alarm_reg = 1'b0;
    end
  end

  assign charge_current = charge_current_reg;
  assign discharge_current = discharge_current_reg;
  assign alarm = alarm_reg;

endmodule

