module top_module (
        input clk,
        input areset,
        input pedestrian_button,
        input walk_timer_done,
        output reg signal);parameter DontWalk = 2'b01, Walk = 2'b10;
	reg [1:0] state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= DontWalk;
		else begin
			case (state)
				DontWalk: state <= pedestrian_button ? Walk : DontWalk;
				Walk: state <= walk_timer_done ? DontWalk : Walk;
			endcase
		end
	end

	assign signal = (state == Walk);
endmodule

