description:
Implement the Verilog module based on the following description.
We want to create a module that:

// (1) receives a 6-bit binary number,
// (2) checks if the number is greater than or equal to 32,
// (3) counts the number of 1s in the binary number,
// (4) outputs a flag if the number is even,
// (5) provides a reset mechanism to reset all outputs.

// The input binary number is available on the input signal 'binary_num'. The output 'is_gte32' should be set to 1 if the number is greater than or equal to 32 and 0 otherwise. The number of 1s in the binary number should be output on 'count_ones[3:0]'. The even number flag should be set on 'is_even' if the number is even. The reset signal is active high synchronous.

module top_module(
    input wire clk,
    input wire reset,
    input wire [5:0] binary_num,
    output reg is_gte32,
    output reg [3:0] count_ones,
    output reg is_even
);

code:
module top_module(
    input wire clk,
    input wire reset,
    input wire [5:0] binary_num,
    output reg is_gte32,
    output reg [3:0] count_ones,
    output reg is_even
);

    integer i;

    always @(posedge clk) begin
        if (reset) begin
            is_gte32 <= 0;
            count_ones <= 0;
            is_even <= 0;
        end else begin
            // Check if greater than or equal to 32
            is_gte32 <= (binary_num >= 6'b100000);

            // Count number of 1s
            count_ones <= 0;
            for (i = 0; i < 6; i = i + 1) begin
                if (binary_num[i]) begin
                    count_ones <= count_ones + 1;
                end
            end

            // Check if even
            is_even <= ~binary_num[0];
        end
    end

endmodule

