      3'b001: G = 3'b001;
      3'b010: G = 3'b011;
      3'b011: G = 3'b010;
      3'b100: G = 3'b110;
      3'b101: G = 3'b111;
      3'b110: G = 3'b101;
      3'b111: G = 3'b100;
    endcase
  end

